class Barang:
    def __init__(self, stok):
        self.stok = stok

    @property
    def stok(self):
        return self._stok

    @stok.setter
    def stok(self, nilai):
        if type(nilai) is not int or nilai < 0:
            raise ValueError("Stok harus integer >= 0")
        self._stok = nilai

barang = Barang(3)
barang.stok = 5
print(barang.stok)
try:
    barang.stok = -1
except ValueError as error:
    print(error)
