class Pelanggan:
    def __init__(self, nama, paket):
        self.nama = nama
        self.paket = paket

    def label(self):
        return f"{self.nama} / {self.paket}"

    @staticmethod
    def valid_nama(nama):
        return isinstance(nama, str) and bool(nama.strip())

    @classmethod
    def dari_teks(cls, teks):
        if not isinstance(teks, str):
            raise ValueError("Format nama|paket diperlukan")
        bagian = teks.split("|")
        if len(bagian) != 2 or not cls.valid_nama(bagian[0]) or not bagian[1].strip():
            raise ValueError("Format nama|paket diperlukan")
        return cls(bagian[0].strip(), bagian[1].strip())

orang = Pelanggan.dari_teks(" Ana | Home ")
print(orang.label())
print(Pelanggan.valid_nama("  "))

class Keranjang:
    def __init__(self, pemilik, item):
        self.pemilik = pemilik
        self.item = list(item)

    def __str__(self):
        return f"Keranjang {self.pemilik}: {len(self)} item"

    def __repr__(self):
        return f"Keranjang({self.pemilik!r}, {self.item!r})"

    def __len__(self):
        return len(self.item)

